import abc
import re

import six
from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandFailure, ParsingDone
from moler.helpers import remove_escape_codes

__author__ = "Agnieszka Bylica"
__copyright__ = "Copyright (C) 2019, Nokia"
__email__ = "agnieszka.bylica@nokia.com"


@six.add_metaclass(abc.ABCMeta)
class Genericasimgr(CommandTextualGeneric):
    """GenericAsiMgr command class."""

    error_codes = {
        "0": "No problems",
        "1": "Common not ok",
        "2": "Invalid operation",
        "3": "Invalid parameters",
        "4": "Site unreachable",
        "5": "Site reserved",
        "6": "Login failed",
        "7": "Unexpected error",
        "8": "Timeout",
        "9": "Password expired",
        "171": "Commission file missing",
    }

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Genericasimgr command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Genericasimgr, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.remove_colors_from_terminal_output = True
        self.current_ret["RESULT"] = []

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._strip_new_lines_chars(line)
                self._parse_finished_with_error(line)
                self._parse_line(line)
            except ParsingDone:
                pass  # line has been fully parsed by one of above parse-methods
        return super(Genericasimgr, self).on_new_line(line, is_full_line)

    def _strip_new_lines_chars(self, line):
        """
        Delete new line chars and other chars we do not need to parse in on_new_line (color escape character).

        :param line: Line with special chars, raw string from device
        :return: line without special chars.
        """
        line = super(Genericasimgr, self)._strip_new_lines_chars(line)
        if self.remove_colors_from_terminal_output:
            line = remove_escape_codes(line)
        return line

    _re_finished_with_error = re.compile(
        r"(?P<TIME>[\d\/]+\s+[\d:]+(\s[AP]M)?)\s+(?P<LEVEL>[A-Z]+)\s+(?P<MSG>.*finished\s+with\s+error\s+code\s+(?P<CODE>\S+))"
    )

    def _parse_finished_with_error(self, line):
        if self._regex_helper.search_compiled(Genericasimgr._re_finished_with_error, line):
            self.current_ret["RESULT"].append(
                {
                    "Time": self._regex_helper.group("TIME"),
                    "Log level": self._regex_helper.group("LEVEL"),
                    "Message": self._regex_helper.group("MSG"),
                }
            )
            error_code = self._regex_helper.group("CODE")
            if error_code in Genericasimgr.error_codes:
                error_code = Genericasimgr.error_codes[error_code]
            self.set_exception(CommandFailure(self, f"{self._regex_helper.group('MSG')}: {error_code}"))
            raise ParsingDone

    _re_line = re.compile(r"(?P<TIME>[\d\/]+\s+[\d:]+(\s[AP]M)?)\s+(?P<LEVEL>[A-Z]+)\s+(?P<MSG>.+)")

    def _parse_line(self, line):
        if self._regex_helper.search_compiled(Genericasimgr._re_line, line):
            self.current_ret["RESULT"].append(
                {
                    "Time": self._regex_helper.group("TIME"),
                    "Log level": self._regex_helper.group("LEVEL"),
                    "Message": self._regex_helper.group("MSG"),
                }
            )
            raise ParsingDone
